/** Open Library serves S / M / L. Cards want M, the detail sheet wants L. */
const SIZES = { small: 'S', medium: 'M', large: 'L' };

const BASE = 'https://covers.openlibrary.org/b/id/';

/**
 * The remote cover URL for a title, or '' when we do not have one.
 *
 * `default=false` makes Open Library return 404 rather than its grey
 * placeholder image, which is what lets the <img> fail cleanly and reveal
 * the generated cover underneath instead of showing a blank box.
 */
export function coverUrlFor(title, size = 'medium') {
  const id = COVER_IDS[title];
  if (!id) return '';
  return `${BASE}${id}-${SIZES[size] ?? 'M'}.jpg?default=false`;
}

/**
 * The full descriptor for a title: the URL, the id it came from, and
 * where it came from.
 *
 * Returns null when we honestly do not have a cover — which is what puts
 * a book on the "still needs a real cover" list instead of quietly giving
 * it a guess. That list is exactly what Phase 2 wants to work through,
 * and nothing more.
 */
export function coverMetaFor(title, size = 'medium') {
  const id = COVER_IDS[title];
  if (!id) return null;
  return { url: coverUrlFor(title, size), coverRef: String(id), source: 'openlibrary' };
}

export const COVER_COUNT = Object.keys(COVER_IDS).length;
export default COVER_IDS;
